    def test_n_kv_heads_divides_n_heads(self):
        """GQA invariant: n_heads % n_kv_heads == 0."""
        with pytest.raises(ValueError):
            MQAConfig(d_model=128, n_heads=8, n_kv_heads=3)

    def test_positive_dimensions(self):
        """All dimensions must be strictly positive."""
