class TestNumericalCorrectness:
    """Compare against a manual reference implementation."""

    def _reference_attention(self, q, k, v, mask=None, dropout_p=0.0):
        """Manual scaled dot-product attention (no GQA grouping)."""
        d_k = q.size(-1)
        scores = torch.matmul(q, k.transpose(-2, -1)) / math.sqrt(d_k)
        if mask is not None:
            scores = scores.masked_fill(mask == 0, float("-inf"))
        attn = F.softmax(scores, dim=-1)
        if dropout_p > 0.0:
            attn = F.dropout(attn, p=dropout_p, training=True)
        return torch.matmul(attn, v)

    def test_forward_shape(self, base_model, sample_inputs):
        """Output shape must match input shape."""
        out = base_model(sample_inputs)
        assert out.shape == sample_inputs.shape

    def test_forward_matches_reference(self, base_model, base_config, sample_inputs):
        """Compare MQA output to manual reference (non-causal for simplicity)."""
        base_model.eval()
        with torch.no_grad():
            # Build manual Q/K/V from the same weights
            W_q = base_model.w_q.weight  # (d_model, d_model)
            W_k = base_model.w_k.weight  # (d_model, d_kv)
            W_v = base_model.w_v.weight  # (d_model, d_kv)
            W_o = base_model.w_o.weight  # (d_model, d_model)

            q = F.linear(sample_inputs, W_q)
            k = F.linear(sample_inputs, W_k)
            v = F.linear(sample_inputs, W_v)

            # Expand KV heads to match Q heads (GQA expansion)
            n_heads = base_config.n_heads
            n_kv_heads = base_config.n_kv_heads
            repeat_factor = n_heads // n_kv_heads

            # Reshape to heads
            batch, seq, _ = q.shape
            d_head = base_config.d_model // n_heads
            d_kv_head = base_config.d_model // n_kv_heads

            q = q.view(batch, seq, n_heads, d_head).transpose(1, 2)
            k = k.view(batch, seq, n_kv_heads, d_kv_head).transpose(1, 2)
            v = v.view(batch, seq, n_kv_heads, d_kv_head).transpose(1, 2)

            # Repeat KV heads
            k = k.repeat_interleave(repeat_factor, dim=1)
            v = v.repeat_interleave(repeat_factor, dim=1)

            # Manual attention (non-causal)
            ref_out = self._reference_attention(q, k, v)
            ref_out = ref_out.transpose(1, 2).contiguous().view(batch, seq, -1)
            ref_out = F.linear(ref_out, W_o)

            # Model output (disable causal for fair comparison)
            model_out = base_model(sample_inputs, causal=False)

            assert torch.allclose(model_out, ref_out, atol=1e-5, rtol=1e-4), \
                f"Max diff: {(model_out - ref_out).abs().max().item()}"

    def test_backward_gradients(self, base_model, sample_inputs):
        """Gradients must flow to all parameters."""
        base_model.train()
        out = base_model(sample_inputs)
        loss = out.sum()
        loss.backward()

        for name, param in base_model.named_parameters():
            assert param.grad is not None, f"Missing gradient for {name}"
            assert torch.isfinite(param.grad).all(), f"Non-finite gradient for {name}"


