class TestCausalMasking:
    """Verify strict lower-triangular masking."""

    def test_causal_no_leakage(self, base_model, base_config, sample_inputs):
        """Position i must not attend to position j > i."""
        base_model.eval()
        with torch.no_grad():
            # Extract attention weights via hook
            attn_weights = {}

            def hook_fn(module, input, output):
                # Assuming module exposes attention weights in output tuple
                if isinstance(output, tuple) and len(output) > 1:
                    attn_weights['weights'] = output[1]

            handle = base_model.register_forward_hook(hook_fn)
            base_model(sample_inputs, causal=True)
            handle.remove()

            if 'weights' in attn_weights:
                weights = attn_weights['weights']
                batch, heads, seq, _ = weights.shape
                for i in range(seq):
                    for j in range(i + 1, seq):
                        # Upper triangular entries must be zero (or -inf before softmax)
                        assert torch.all(weights[:, :, i, j] == 0), \
                            f"Leakage detected at position ({i}, {j})"

    def test_causal_output_equals_non_causal_for_first_token(self, base_model, sample_inputs):
        """First token has no causal restriction; outputs should match."""
        base_model.eval()
        with torch.no_grad():
            causal_out = base_model(sample_inputs, causal=True)
            non_causal_out = base_model(sample_inputs, causal=False)
            # First token position
            assert torch.allclose(causal_out[:, 0, :], non_causal_out[:, 0, :], atol=1e-6)


