class TestGQAHeadGrouping:
    """Validate KV head expansion."""

    def test_kv_head_expansion(self, base_config, base_model):
        """KV weight shapes must reflect n_kv_heads, not n_heads."""
        assert base_model.w_k.weight.shape[0] == base_config.d_model
        assert base_model.w_k.weight.shape[1] == base_config.d_model // base_config.n_kv_heads
        assert base_model.w_v.weight.shape[1] == base_config.d_model // base_config.n_kv_heads

    def test_repeat_factor(self, base_config):
        """Repeat factor = n_heads / n_kv_heads."""
        assert base_config.n_heads % base_config.n_kv_heads == 0
        repeat = base_config.n_heads // base_config.n_kv_heads
        assert repeat == 4  # 8/2

    def test_output_equals_full_attention(self, base_config):
        """GQA with n_kv_heads == n_heads should equal MHA."""
        mha_cfg = MQAConfig(
            d_model=base_config.d_model,
            n_heads=base_config.n_heads,
            n_kv_heads=base_config.n_heads,
        )
        mha = MultiQueryAttention(mha_cfg)
        gqa = MultiQueryAttention(base_config)

        # Copy weights from GQA to MHA (expand KV)
        with torch.no_grad():
            mha.w_k.weight.copy_(gqa.w_k.weight.repeat_interleave(4, dim=1))
            mha.w_v.weight.copy_(gqa.w_v.weight.repeat_interleave(4, dim=1))
            mha.w_q.weight.copy_(gqa.w_q.weight)
            mha.w_o.weight.copy_(gqa.w_o.weight)

        torch.manual_seed(0)
        x = torch.randn(2, 8, base_config.d_model)
        mha.eval()
        gqa.eval()
        with torch.no_grad():
            out_mha = mha(x)
            out_gqa = gqa(x)
        assert torch.allclose(out_mha, out_gqa, atol=1e-5)


