class TestPrecisionPaths:
    """Validate FP16/BF16/INT8 paths."""

    @pytest.mark.parametrize("dtype", [torch.float16, torch.bfloat16])
    def test_half_precision(self, base_model, base_config, dtype):
        """Half precision forward pass must not crash and produce finite outputs."""
        if not torch.cuda.is_available() and dtype == torch.float16:
            pytest.skip("FP16 requires CUDA")
        base_model = base_model.to(dtype)
        x = torch.randn(2, 8, base_config.d_model, dtype=dtype)
        base_model.eval()
        with torch.no_grad():
            out = base_model(x)
        assert out.dtype == dtype
        assert torch.isfinite(out).all()

    def test_int8_simulation(self, base_model, base_config):
        """Simulated INT8 quantization via scaling."""
        # Simulate INT8 by scaling weights to [-127, 127] and rounding
        with torch.no_grad():
            for param in base_model.parameters():
                param.mul_(127.0 / param.abs().max())
                param.round_()

        x = torch.randn(1, 4, base_config.d_model)
        base_model.eval()
        with torch.no_grad():
            out = base_model(x)
        assert torch.isfinite(out).all()

    def test_mixed_precision_autocast(self, base_model, base_config):
        """Autocast should work on CUDA."""
        if not torch.cuda.is_available():
            pytest.skip("CUDA not available")
        x = torch.randn(2, 8, base_config.d_model)
        base_model = base_model.cuda()
        with torch.autocast(device_type="cuda", dtype=torch.float16):
            out = base_model(x.cuda())
        assert out.dtype == torch.float16


