class TestTelemetry:
    """Validate FLOPs and memory bandwidth counters."""

    def test_flops_monotonic(self, base_model, base_config, sample_inputs):
        """FLOPs should increase with sequence length."""
        flops_short = base_model.compute_flops(seq_len=8)
        flops_long = base_model.compute_flops(seq_len=16)
