    def test_flops_plausibility(self, base_model, base_config):
        """FLOPs should be positive and scale with d_model^2."""
        flops = base_model.compute_flops(seq_len=1)
        assert flops > 0
        # Rough estimate: 4 * d_model^2 per token (QKV + output projections)
        expected_min = 4 * base_config.d_model ** 2
        assert flops >= expected_min

    def test_memory_bandwidth(self, base_model, base_config):
        """Bandwidth should be positive and increase with batch size."""
        bw_1 = base_model.compute_memory_bandwidth(batch=1, seq_len=16)
        bw_2 = base_model.compute_memory_bandwidth(batch=2, seq_len=16)
        assert bw_1 > 0
        assert bw_2 > bw_1


