class TestDeterminism:
    """Same input must produce same output across runs."""

    def test_deterministic_output(self, base_model, base_config):
        """Eval mode should be deterministic."""
        torch.manual_seed(123)
        x = torch.randn(2, 8, base_config.d_model)
        base_model.eval()
        with torch.no_grad():
            out1 = base_model(x)
            out2 = base_model(x)
        assert torch.equal(out1, out2)

    def test_seed_control(self, base_model, base_config):
        """Different seeds should produce different outputs (training mode)."""
        base_model.train()
        x = torch.randn(2, 8, base_config.d_model)

        torch.manual_seed(0)
        out1 = base_model(x)

        torch.manual_seed(1)
        out2 = base_model(x)

        assert not torch.allclose(out1, out2)